def mini_startswith(s, prefix):
    # 生效条件：s/prefix 均为字符串
    # 子功能：① 空前缀返 True；② 逐位比对前 len(prefix) 字符；③ 不匹配返 False
    # 执行：循环迭代；条件分派
    # 不适用条件：任意位置子串匹配（用 mini_contains）；不用内建 startswith
    if len(prefix) > len(s):
        return False
    for i in range(len(prefix)):
        if s[i] != prefix[i]:
            return False
    return True

def mini_endswith(s, suffix):
    # 生效条件：s/suffix 均为字符串
    # 子功能：① 空后缀返 True；② 从尾部对齐逐位比对；③ 不匹配返 False
    # 执行：循环迭代；条件分派
    # 不适用条件：多后缀元组形式不在本单元范围；不用内建 endswith
    if len(suffix) > len(s):
        return False
    offset = len(s) - len(suffix)
    for i in range(len(suffix)):
        if s[offset + i] != suffix[i]:
            return False
    return True

def clamp(v, lo, hi):
    # 生效条件：v/lo/hi 为可比较数值且 lo <= hi
    # 子功能：① v < lo 返回 lo；② v > hi 返回 hi；③ 否则返回 v
    # 执行：条件分派
    # 不适用条件：lo > hi 时行为未定义（前置条件违背）；不用内建 min/max 组合
    if v < lo:
        return lo
    if v > hi:
        return hi
    return v
